using System;using System.IO;using System.Linq;using UnityEngine;using Unity.Cinemachine;using UnityEditor;using UnityEditor.SceneManagement;public static class SetupTownPan{public static object Main(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Clean edit required");File.Copy(s.path,"output/scene-review/Main.before-townpan-disk.unity",true);EditorSceneManager.SaveScene(s,"output/scene-review/Main.before-townpan-live.unity",true);var c=UnityEngine.Object.FindObjectsByType<CinemachineCamera>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(v=>v.Follow!=null&&v.Follow.name=="Hometown");var home=c.Follow;var target=new GameObject("Town Camera Pan Target");Undo.RegisterCreatedObjectUndo(target,"Town camera pan target");target.transform.SetParent(home,false);var boundary=new GameObject("Town Camera Land Bounds");Undo.RegisterCreatedObjectUndo(boundary,"Town camera boundary");boundary.transform.SetParent(home,false);boundary.layer=2;var box=boundary.AddComponent<BoxCollider2D>();box.isTrigger=true;box.size=new Vector2(127,107);var conf=Undo.AddComponent<CinemachineConfiner2D>(c.gameObject);conf.BoundingShape2D=box;conf.Damping=0;conf.SlowingDistance=0;Undo.RecordObject(c,"Follow independent town target");c.Follow=target.transform;var follow=c.GetComponent<CinemachineFollow>();Undo.RecordObject(follow,"Responsive town camera smoothing");follow.TrackerSettings.PositionDamping=new Vector3(.15f,.15f,0);var pan=Undo.AddComponent<TimelessEchoes.TownCameraPan>(c.gameObject);var so=new SerializedObject(pan);so.FindProperty("panTarget").objectReferenceValue=target.transform;so.FindProperty("landBounds").objectReferenceValue=box;so.FindProperty("outputCamera").objectReferenceValue=Camera.main;so.ApplyModifiedProperties();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s,"output/scene-review/Main.after-townpan-live.unity",true);return new{camera=c.name,boundsWidth=box.size.x,boundsHeight=box.size.y};}}
